package com.bmd.scanner;
import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;
public class PicklistDataTest {
    static PicklistData.Page page(String digest,String...lines){return new PicklistData.Page(Arrays.asList(lines),digest);}
    @Test public void shipmentTableColumnsDoNotConfuseBackorderWithEnclosed(){PicklistData p=PicklistData.parse(Arrays.asList(page("1","Shipment list 20260876","Order 20260488","PRO2020 Protégé DEB PTCA Cath. 2020 0 4 2610129 2028-04-15","PRO2030 Protégé DEB PTCA Cath. 2030 0 3 2610092 2028-04-08","PRO2520 Protégé DEB PTCA Cath. 2520 0 7 2610139 2028-04-18","PRO2530 Protégé DEB PTCA Cath. 2530 0 8 2610151 2028-04-19","PRO3030 Protégé DEB PTCA Cath. 3030 0 2 2610103 2028-04-11","PRO3520 Protégé DEB PTCA Cath. 3520 0 2 2610112 2028-04-13","PRO3530 Protégé DEB PTCA Cath. 3530 0 2 2610136 2028-04-15","Total 0 28","Page 1 of 1")));assertTrue(p.consistent());assertEquals(7,p.rows.size());assertEquals(28,p.total());assertEquals("shipment",p.kind);assertEquals("20260488",p.order);assertEquals("2610129",p.rows.get(0).lot);}
    @Test public void missingPagesAndUnreadableRowsRemainUncertain(){PicklistData p=PicklistData.parse(Arrays.asList(page("2","PRO2515 0 3 2607305 2028-01-30","Total 0 3","Page 2 of 2")));assertEquals(1,p.missingPages);assertFalse(p.consistent());PicklistData q=PicklistData.parse(Arrays.asList(page("x","PRO2020 unreadable","Total 0 4")));assertEquals(1,q.unparsed);assertFalse(q.consistent());}
    @Test(expected=IllegalArgumentException.class)public void duplicateSourcePageCannotDoubleTheOrder(){PicklistData.parse(Arrays.asList(page("same","PRO2020 4 2610129 2028-04-15"),page("same","PRO2020 4 2610129 2028-04-15")));}
    @Test public void matchingGrandTotalDoesNotHideWrongLotsArticlesOrExpiry(){PicklistData.Row r=new PicklistData.Row("PRO2020","2610129","2028-04-15",4,false);assertFalse(PicklistData.within(Arrays.asList(r),Collections.singletonMap("PRO2020|2610139|2028-04-15",4)));assertFalse(PicklistData.within(Arrays.asList(r),Collections.singletonMap("PRO2030|2610129|2028-04-15",4)));assertFalse(PicklistData.within(Arrays.asList(r),Collections.singletonMap("PRO2020|2610129|2028-04-16",4)));assertTrue(PicklistData.within(Arrays.asList(r),Collections.singletonMap(r.key(),4)));}
    @Test public void expiryAndPrintedTotalAreValidated(){assertEquals("2028-04-30",PicklistData.date("280400"));assertEquals("",PicklistData.date("2028-02-31"));PicklistData p=PicklistData.parse(Arrays.asList(page("a","PRO2020 4 2610129 2028-04-15","Total 5")));assertFalse(p.consistent());}
}
